#!/usr/bin/env bash
# Generated by build.py. Writes the fixture project into the empty workspace.
set -euo pipefail
ago() { python3 -c 'import datetime as d,sys; print((d.datetime.now(d.timezone.utc) - d.timedelta(hours=float(sys.argv[1]))).strftime("%Y-%m-%dT%H:%MZ"))' "$1"; }
