module "schedule" {
  source  = "example/datekit/generic"
  version = "2.6.1"

  date_format = "iso8601"
}
FIXTURE
cat > '.terraform.lock.hcl' <<'FIXTURE'
# This file is maintained automatically by "terraform init".
# Manual edits may be lost in future updates.

provider "registry.terraform.io/example/fastqueue" {
  version     = "1.3.0"
  constraints = "1.3.0"
  hashes = [
    "h1:QQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQ=",
    "zh:1111111111111111111111111111111111111111111111111111111111111111",
  ]
}
FIXTURE
mkdir -p '.github'
cat > '.github/dependabot.yml' <<'FIXTURE'
version: 2
updates:
  - package-ecosystem: "terraform"
    directory: "/"
    schedule:
      interval: "weekly"
    cooldown:
      default-days: 3
FIXTURE
